CREATE TABLE client_progress_statement_costs(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,statement_id BIGINT UNSIGNED NOT NULL,project_actual_cost_id BIGINT UNSIGNED NOT NULL,is_committed TINYINT(1) NOT NULL DEFAULT 0,cost_date_snapshot DATE NULL,description_snapshot VARCHAR(500) NULL,reference_number_snapshot VARCHAR(190) NULL,work_section_code_snapshot VARCHAR(20) NULL,work_section_name_snapshot VARCHAR(190) NULL,cost_code_snapshot VARCHAR(30) NULL,cost_code_name_snapshot VARCHAR(255) NULL,vendor_code_snapshot VARCHAR(30) NULL,vendor_name_snapshot VARCHAR(190) NULL,amount_snapshot DECIMAL(18,2) NULL,source_type_snapshot VARCHAR(50) NULL,committed_project_actual_cost_id BIGINT UNSIGNED AS(CASE WHEN is_committed=1 THEN project_actual_cost_id ELSE NULL END) PERSISTENT,sort_order INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_cps_cost_statement(statement_id,project_actual_cost_id),UNIQUE KEY uq_cps_cost_committed(committed_project_actual_cost_id),KEY idx_cps_cost_actual(project_actual_cost_id),CONSTRAINT fk_cps_cost_statement FOREIGN KEY(statement_id) REFERENCES client_progress_statements(id) ON DELETE RESTRICT,CONSTRAINT fk_cps_cost_actual FOREIGN KEY(project_actual_cost_id) REFERENCES project_actual_costs(id) ON DELETE RESTRICT,CONSTRAINT chk_cps_cost_committed CHECK(is_committed IN(0,1)),CONSTRAINT chk_cps_cost_snapshots CHECK((is_committed=0 AND cost_date_snapshot IS NULL AND description_snapshot IS NULL AND reference_number_snapshot IS NULL AND work_section_code_snapshot IS NULL AND work_section_name_snapshot IS NULL AND cost_code_snapshot IS NULL AND cost_code_name_snapshot IS NULL AND vendor_code_snapshot IS NULL AND vendor_name_snapshot IS NULL AND amount_snapshot IS NULL AND source_type_snapshot IS NULL) OR(is_committed=1 AND cost_date_snapshot IS NOT NULL AND description_snapshot IS NOT NULL AND work_section_code_snapshot IS NOT NULL AND work_section_name_snapshot IS NOT NULL AND cost_code_snapshot IS NOT NULL AND cost_code_name_snapshot IS NOT NULL AND amount_snapshot>0 AND source_type_snapshot IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
